/* Detective clue artwork: local SVG assets, independent of system emoji fonts. */
(()=>{'use strict';
const items=Object.freeze([{"id":"apple","label":"Яблоко"},{"id":"pear","label":"Груша"},{"id":"banana","label":"Банан"},{"id":"grapes","label":"Виноград"},{"id":"strawberry","label":"Клубника"},{"id":"cherries","label":"Вишня"},{"id":"watermelon","label":"Арбуз"},{"id":"pineapple","label":"Ананас"},{"id":"carrot","label":"Морковь"},{"id":"mushroom","label":"Гриб"},{"id":"bread","label":"Хлеб"},{"id":"pizza","label":"Пицца"},{"id":"donut","label":"Пончик"},{"id":"ice-cream","label":"Мороженое"},{"id":"cupcake","label":"Кекс"},{"id":"cheese","label":"Сыр"},{"id":"honey","label":"Мёд"},{"id":"lollipop","label":"Леденец"},{"id":"kettle","label":"Чайник"},{"id":"mug","label":"Кружка"},{"id":"key","label":"Ключ"},{"id":"book","label":"Книга"},{"id":"pencil","label":"Карандаш"},{"id":"scissors","label":"Ножницы"},{"id":"magnifier","label":"Лупа"},{"id":"camera","label":"Фотоаппарат"},{"id":"clock","label":"Будильник"},{"id":"telephone","label":"Телефон"},{"id":"lamp","label":"Настольная лампа"},{"id":"flashlight","label":"Фонарик"},{"id":"umbrella","label":"Зонт"},{"id":"hat","label":"Шляпа"},{"id":"crown","label":"Корона"},{"id":"glasses","label":"Очки"},{"id":"mitten","label":"Варежка"},{"id":"sock","label":"Носок"},{"id":"boot","label":"Сапог"},{"id":"backpack","label":"Рюкзак"},{"id":"bow-tie","label":"Бабочка-галстук"},{"id":"watch","label":"Наручные часы"},{"id":"teddy","label":"Плюшевый мишка"},{"id":"ball","label":"Футбольный мяч"},{"id":"dice","label":"Игральный кубик"},{"id":"puzzle","label":"Пазл"},{"id":"gift","label":"Подарок"},{"id":"balloon","label":"Воздушный шар"},{"id":"kite","label":"Воздушный змей"},{"id":"rocket","label":"Ракета"},{"id":"car","label":"Автомобиль"},{"id":"train","label":"Паровоз"},{"id":"guitar","label":"Гитара"},{"id":"drum","label":"Барабан"},{"id":"trumpet","label":"Труба"},{"id":"bell","label":"Колокольчик"},{"id":"palette","label":"Палитра"},{"id":"paintbrush","label":"Кисть"},{"id":"flower","label":"Цветок"},{"id":"cactus","label":"Кактус"},{"id":"leaf","label":"Лист"},{"id":"shell","label":"Ракушка"},{"id":"cat","label":"Кошка"},{"id":"dog","label":"Собака"},{"id":"owl","label":"Сова"},{"id":"butterfly","label":"Бабочка"},{"id":"turtle","label":"Черепаха"},{"id":"frog","label":"Лягушка"},{"id":"fish","label":"Рыба"},{"id":"ladybug","label":"Божья коровка"},{"id":"bird","label":"Птица"},{"id":"snail","label":"Улитка"}].map(Object.freeze));
// SVG artwork is bundled into this single JavaScript file. No 70 separate
// image requests on startup, even when the GitVerse host is slow.
const artwork=Object.freeze({"apple":"","pear":"","banana":"","grapes":"","strawberry":"","cherries":"","watermelon":"","pineapple":"","carrot":"","mushroom":"","bread":"","pizza":"","donut":"","ice-cream":"","cupcake":"","cheese":"","honey":"","lollipop":"","kettle":"","mug":"","key":"","book":"","pencil":"","scissors":"","magnifier":"","camera":"","clock":"","telephone":"","lamp":"","flashlight":"","umbrella":"","hat":"","crown":"","glasses":"","mitten":"","sock":"","boot":"","backpack":"","bow-tie":"","watch":"","teddy":"","ball":"","dice":"","puzzle":"","gift":"","balloon":"","kite":"","rocket":"","car":"","train":"","guitar":"","drum":"","trumpet":"","bell":"","palette":"","paintbrush":"","flower":"","cactus":"","leaf":"","shell":"","cat":"","dog":"","owl":"","butterfly":"","turtle":"","frog":"","fish":"","ladybug":"","bird":"","snail":""});
const byId=new Map(items.map(item=>[item.id,item]));
const sources=new Map();
function source(id){
 if(!Object.prototype.hasOwnProperty.call(artwork,id))return '';
 if(!sources.has(id))sources.set(id,'data:image/svg+xml;base64,'+artwork[id]);
 return sources.get(id);
}
function markup(id){
 const item=byId.get(id);
 return item?'<img class="detective-clue" src="'+source(id)+'" alt="'+item.label+'" width="96" height="96" draggable="false" decoding="sync">':'';
}
function mount(target,id){
 target.innerHTML=markup(id);
 if(byId.has(id))target.dataset.clue=id;else delete target.dataset.clue;
}
// Decode only the icons needed in the current round. The countdown starts
// after those particular images are ready, never after the full 70-item set.
const decoded=new Set();
const decoding=new Map();
function prepare(id){
 if(decoded.has(id))return Promise.resolve();
 if(decoding.has(id))return decoding.get(id);
 const promise=new Promise((resolve,reject)=>{
  const img=new Image();
  img.onload=()=>{
   if(img.decode)img.decode().then(resolve,resolve);
   else resolve();
  };
  img.onerror=()=>reject(new Error('Ошибка загрузки изображения: '+id));
  img.src=source(id);
 }).then(()=>{decoded.add(id)}).finally(()=>{decoding.delete(id)});
 decoding.set(id,promise);
 return promise;
}
function preload(ids=[]){
 const selected=Array.isArray(ids)?ids:[];
 return Promise.all([...new Set(selected)].filter(id=>byId.has(id)).map(prepare)).then(()=>undefined);
}
window.NeuroXDetectiveIcons=Object.freeze({version:'detective-svg-70-v1',items,markup,mount,preload});
})();
